CREATE TEMPORARY VIEW dwd_raw_data_version_filtered_${grass_region_without_quote} AS
SELECT
    user_id
    ,platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,operation
    ,search_session_id
    ,is_cache
    ,stages
    ,total_duration
    ,server_cost
    ,request_pack_size
    ,response_pack_size
FROM 
