WHERE (
        CAST(SPLIT(app_version, '\\.')[0] AS INT) > 3
        OR (CAST(SPLIT(app_version, '\\.')[0] AS INT) = 3 AND CAST(SPLIT(app_version, '\\.')[1] AS INT) > 27)
        OR (CAST(SPLIT(app_version, '\\.')[0] AS INT) = 3 AND CAST(SPLIT(app_version, '\\.')[1] AS INT) = 27 AND CAST(SPLIT(app_version, '\\.')[2] AS INT) >= 0)
    ) AND (
        CAST(SPLIT(dre_version, '\\.')[0] AS INT) > 1
        OR (CAST(SPLIT(dre_version, '\\.')[0] AS INT) = 1 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) > 50)
        OR (CAST(SPLIT(dre_version, '\\.')[0] AS INT) = 1 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) = 50 AND CAST(SPLIT(dre_version, '\\.')[2] AS INT) >= 2)
    );

