CREATE TEMPORARY VIEW total_duration_and_response_pack_size_pcts_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,platform
    ,IF(GROUPING(layout_variant) = 1, '__ALL__', layout_variant) AS layout_variant
    ,IF(GROUPING(app_version) = 1, '__ALL__', app_version) AS app_version
    ,IF(GROUPING(dre_version) = 1, '__ALL__', dre_version) AS dre_version
    ,operation
    ,APPROX_PERCENTILE(total_duration, ARRAY(0.8, 0.9, 0.95, 0.99), 2000) AS total_duration_pcts
    ,APPROX_PERCENTILE(response_pack_size, ARRAY(0.8, 0.9, 0.95, 0.99), 2000) AS response_pack_size_pcts
FROM
    total_duration_and_be_stats_user_level_all_metrics_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY 
    experiment_id
    ,exp_group_id
    ,platform
    ,CUBE(layout_variant, app_version, dre_version)
    ,operation;

