CREATE TEMPORARY VIEW dws_total_duration_and_be_statistics_merge_${grass_region_without_quote} AS
SELECT
    COALESCE(a.experiment_id, b.experiment_id, c.experiment_id) AS experiment_id
    ,COALESCE(a.exp_group_id, b.exp_group_id, c.exp_group_id) AS exp_group_id
    ,COALESCE(a.platform, b.platform, c.platform) AS platform
    ,COALESCE(a.layout_variant, b.layout_variant, c.layout_variant) AS layout_variant
    ,COALESCE(a.app_version, b.app_version, c.app_version) AS app_version
    ,COALESCE(a.dre_version, b.dre_version, c.dre_version) AS dre_version
    ,COALESCE(a.operation, b.operation, c.operation) AS operation
    ,total_duration_pcts[0] AS total_duration_p80
    ,total_duration_pcts[1] AS total_duration_p90
    ,total_duration_pcts[2] AS total_duration_p95
    ,total_duration_pcts[3] AS total_duration_p99
    ,server_cost_pcts[0] AS server_cost_p80
    ,server_cost_pcts[1] AS server_cost_p90
    ,server_cost_pcts[2] AS server_cost_p95
    ,server_cost_pcts[3] AS server_cost_p99
    ,request_pack_size_pcts[0] AS request_pack_size_p80
    ,request_pack_size_pcts[1] AS request_pack_size_p90
    ,request_pack_size_pcts[2] AS request_pack_size_p95
    ,request_pack_size_pcts[3] AS request_pack_size_p99
    ,response_pack_size_pcts[0] AS response_pack_size_p80
    ,response_pack_size_pcts[1] AS response_pack_size_p90
    ,response_pack_size_pcts[2] AS response_pack_size_p95
    ,response_pack_size_pcts[3] AS response_pack_size_p99
FROM
    total_duration_and_response_pack_size_pcts_${grass_region_without_quote} a
FULL JOIN
    server_cost_pcts_${grass_region_without_quote} b
ON
    a.experiment_id = b.experiment_id
    AND a.exp_group_id = b.exp_group_id
    AND a.platform = b.platform
    AND a.layout_variant = b.layout_variant
    AND a.app_version = b.app_version
    AND a.dre_version = b.dre_version
    AND a.operation = b.operation
FULL JOIN
    request_pack_size_pcts_${grass_region_without_quote} c
ON
    COALESCE(a.experiment_id, b.experiment_id) = c.experiment_id
    AND COALESCE(a.exp_group_id, b.exp_group_id) = c.exp_group_id
    AND COALESCE(a.platform, b.platform) = c.platform
    AND COALESCE(a.layout_variant, b.layout_variant) = c.layout_variant
    AND COALESCE(a.app_version, b.app_version) = c.app_version
    AND COALESCE(a.dre_version, b.dre_version) = c.dre_version
    AND COALESCE(a.operation, b.operation) = c.operation;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_load_times_${grass_region_without_quote} AS
SELECT
    user_id
    ,platform
    ,IF(GROUPING(layout_variant) = 1, '__ALL__', layout_variant) AS layout_variant
    ,IF(GROUPING(app_version) = 1, '__ALL__', app_version) AS app_version
    ,IF(GROUPING(dre_version) = 1, '__ALL__', dre_version) AS dre_version
    ,operation
    ,search_session_id
    ,COUNT(1) AS load_times
FROM
    dwd_raw_data_version_filtered_${grass_region_without_quote}
GROUP BY
    user_id, platform, CUBE(layout_variant, app_version, dre_version), operation, search_session_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW load_times_flatten_${grass_region_without_quote} AS
-- To give pagination & filter operations 0 load_times value under the same dimensions which has business meaning
SELECT
    user_id
    ,platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,search_session_id
    ,SUM(IF(operation = 'action_first_page_performance', load_times, 0)) AS first_page_load_times
    ,SUM(IF(operation = 'action_pagination_performance', load_times, 0)) AS pagination_load_times
    ,SUM(IF(operation = 'action_filter_performance', load_times, 0)) AS filter_load_times
    ,COUNT(IF(operation = 'action_first_page_performance', 1, NULL)) AS first_page_count
    ,COUNT(IF(operation = 'action_pagination_performance', 1, NULL)) AS pagination_count
    ,COUNT(IF(operation = 'action_filter_performance', 1, NULL)) AS filter_count
FROM
    dwd_load_times_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_load_times_exploded_${grass_region_without_quote} AS
SELECT
-- Add back on operation column
-- num_count to remove phantom rows generated where there is completely no pagination or filter from source data
    user_id
    ,platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,exploded.operation AS operation
    ,exploded.load_time AS load_times
FROM
    load_times_flatten_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(
        STRUCT('action_first_page_performance' AS operation, first_page_load_times AS load_time, first_page_count AS num_count)
        ,STRUCT('action_pagination_performance' AS operation, pagination_load_times AS load_time, pagination_count AS num_count)
        ,STRUCT('action_filter_performance' AS operation, filter_load_times AS load_time, filter_count AS num_count)
    )) AS exploded
WHERE
    exploded.num_count IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_load_times_count_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,operation
    ,load_times
    ,COUNT(1) AS load_times_count
FROM
    dwm_load_times_exploded_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_load_times_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,operation
    ,SUM(load_times * load_times_count) / SUM(load_times_count) AS avg_load_times
    ,PERCENTILE(load_times, ARRAY(0.5, 0.8, 0.9, 0.95, 0.99), load_times_count) AS load_times_pcts
FROM
    dwm_load_times_count_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6,7;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_cache_success_rate_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,platform
    ,IF(GROUPING(layout_variant) = 1, '__ALL__', layout_variant) AS layout_variant
    ,IF(GROUPING(app_version) = 1, '__ALL__', app_version) AS app_version
    ,IF(GROUPING(dre_version) = 1, '__ALL__', dre_version) AS dre_version
    ,SUM(IF(is_cache = 'true', 1, 0)) / COUNT(1) AS cache_success_rate
FROM
    dwd_raw_data_version_filtered_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    operation = 'action_first_page_performance'
GROUP BY
    experiment_id, exp_group_id, platform, CUBE(layout_variant, app_version, dre_version);

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_search_abtest_app_performance_monitor_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
-- duration metrics are at operation + stage granularity which is seperate from the other metrics
SELECT
/*+ REPARTITION(200) */
    a.experiment_id
    ,a.exp_group_id
    ,duration_p80
    ,duration_p90
    ,duration_p95
    ,duration_p99
    ,NULL AS total_duration_p80
    ,NULL AS total_duration_p90
    ,NULL AS total_duration_p95
    ,NULL AS total_duration_p99
    ,NULL AS server_cost_p80
    ,NULL AS server_cost_p90
    ,NULL AS server_cost_p95
    ,NULL AS server_cost_p99
    ,NULL AS request_pack_size_p80
    ,NULL AS request_pack_size_p90
    ,NULL AS request_pack_size_p95
    ,NULL AS request_pack_size_p99
    ,NULL AS response_pack_size_p80
    ,NULL AS response_pack_size_p90
    ,NULL AS response_pack_size_p95
    ,NULL AS response_pack_size_p99
    ,NULL AS avg_load_times
    ,NULL AS p50_load_times
    ,NULL AS p80_load_times
    ,NULL AS p90_load_times
    ,NULL AS p95_load_times
    ,NULL AS p99_load_times
    ,NULL AS cache_success_rate
    ,group_uu
    ,search_uu
    ,search_volume
    ,platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,operation
    ,stage
    ,category_level
    ,parent_stage
    ,client_type
FROM
    dws_all_stage_duration_merge_${grass_region_without_quote} a
LEFT JOIN
    exp_group_uu_${grass_region_without_quote} b
ON
    a.experiment_id = b.experiment_id
    AND a.exp_group_id = b.exp_group_id
LEFT JOIN
    search_uu_${grass_region_without_quote} c
ON
    a.experiment_id = c.experiment_id
    AND a.exp_group_id = c.exp_group_id
LEFT JOIN
    search_volume_${grass_region_without_quote} d
ON
    a.experiment_id = d.experiment_id
    AND a.exp_group_id = d.exp_group_id
UNION ALL
SELECT
/*+ REPARTITION(200) */
    a.experiment_id AS experiment_id
    ,a.exp_group_id AS exp_group_id
    ,NULL AS duration_p80
    ,NULL AS duration_p90
    ,NULL AS duration_p95
    ,NULL AS duration_p99
    ,total_duration_p80
    ,total_duration_p90
    ,total_duration_p95
    ,total_duration_p99
    ,server_cost_p80
    ,server_cost_p90
    ,server_cost_p95
    ,server_cost_p99
    ,request_pack_size_p80
    ,request_pack_size_p90
    ,request_pack_size_p95
    ,request_pack_size_p99
    ,response_pack_size_p80
    ,response_pack_size_p90
    ,response_pack_size_p95
    ,response_pack_size_p99
    ,avg_load_times
    ,load_times_pcts[0] AS p50_load_times
    ,load_times_pcts[1] AS p80_load_times
    ,load_times_pcts[2] AS p90_load_times
    ,load_times_pcts[3] AS p95_load_times
    ,load_times_pcts[4] AS p99_load_times
    ,cache_success_rate
    ,group_uu
    ,search_uu
    ,search_volume
    ,a.platform AS platform
    ,a.layout_variant AS layout_variant
    ,a.app_version AS app_version
    ,a.dre_version AS dre_version
    ,a.operation AS operation
    ,'__ALL__' AS stage
    ,NULL AS category_level
    ,NULL AS parent_stage
    ,NULL AS client_type
FROM
    dws_total_duration_and_be_statistics_merge_${grass_region_without_quote} a
LEFT JOIN
    dws_load_times_${grass_region_without_quote} b
ON
    a.platform = b.platform
    AND a.layout_variant = b.layout_variant
    AND a.app_version = b.app_version
    AND a.dre_version = b.dre_version
    AND a.operation = b.operation
    AND a.experiment_id = b.experiment_id
    AND a.exp_group_id = b.exp_group_id
LEFT JOIN
    dws_cache_success_rate_${grass_region_without_quote} c
ON
    a.platform = c.platform
    AND a.layout_variant = c.layout_variant
    AND a.app_version = c.app_version
    AND a.dre_version = c.dre_version
    AND a.operation = 'action_first_page_performance'
    AND a.experiment_id = c.experiment_id
    AND a.exp_group_id = c.exp_group_id
LEFT JOIN
    exp_group_uu_${grass_region_without_quote} d
ON
    a.experiment_id = d.experiment_id
    AND a.exp_group_id = d.exp_group_id
LEFT JOIN
    search_uu_${grass_region_without_quote} e
ON
    a.experiment_id = e.experiment_id
    AND a.exp_group_id = e.exp_group_id
LEFT JOIN
    search_volume_${grass_region_without_quote} f
ON
    a.experiment_id = f.experiment_id
    AND a.exp_group_id = f.exp_group_id;
